    def _encode_data(
        self,
        method: _Method,
        payload: BaseModel,
        *,
        encode_json: bool,
    ) -> dict[str, Any]:
        """This deals with weird J1 request encoding.

        * sometimes it's an URLENCODED json within a "data" param
        * sometimes it's standard URLENCODED form params, in a POST
        * sometimes it's standard URLENCODED form params, in a GET
        """
        if method == "POST":
            if encode_json:
                return {
                    "data": {
                        "data": payload.model_dump_json(
                            exclude_unset=True,
                            by_alias=True,
                        ),
                    },
                }

            return {"data": payload.model_dump(exclude_unset=True, by_alias=True)}

        return {"params": payload.model_dump(exclude_unset=True, by_alias=True)}

    async def _make_request(  # noqa: WPS238,WPS231
        self,
        method: _Method,
        url: str,
        payload: BaseModel,
        rate_limit_timeout: float | None = 60,
        *,
        encode_json: bool = False,
    ) -> models.Response:
        if hasattr(payload, "org_id"):  # noqa: WPS421
            payload.org_id = payload.org_id or self._get_org_id_from_auth()
        if self._rate_limit_client and rate_limit_timeout:
            try:
                await self._rate_limit_client.rate_limit(timeout=rate_limit_timeout)
            except TimeoutError as raw_exc:
                raise errors.AsyncTimeOutError(inspect.getdoc(raw_exc)) from raw_exc

        try:
            response = await self._http_client.request(
                method=method,
                url=self._api_base_url.copy_with(path=url),
                timeout=self.timeout,
                **self._encode_data(method, payload, encode_json=encode_json),
            )
        except httpx.TimeoutException as timeout_exc:
            raise errors.TimeOutError.from_error(timeout_exc) from timeout_exc
        except httpx.RequestError as request_exc:
            raise errors.RequestError.from_error(request_exc) from request_exc

        try:
            response.raise_for_status()
        except httpx.HTTPStatusError as exc:
            raise errors.HttpStatusError.from_error(exc) from exc

        response_model = models.Response(**response.json())

        if response_model.status == auto_models.ResponseStatus.failed:
            raise errors.ProtocolError.from_error(response_model, response)

        return response_model

    def _get_org_id_from_auth(self) -> int | None:
        auth = self._http_client.auth
        if not auth or not isinstance(auth, TemporaryTokenAuth):
            return None
        return auth.get_org_id()
